n18.  Antiasma(salbutamol tab/cairan inh/sirup/MDI/Aerosol/serb inh+rotahaler, aminofolin tab 150mg/200mg, aminofilin inj, budesonid serb ih/cairan ih, epinefrin, fenoterol aerosol/cairan ih, Flutikason, ipratropium bromida, kombinasi budenosid-formoterol, kombinasi ipratropium bromida dan fenotrol/salbutamol, Kombinasi Salmeterol-flutikason propionat, metilprednisolon 4mg/8mg, metilprednisolon inj 125 mg, Prednison 5mg, Teofilin 150mg/300mg, terbutalin tab/inj/cairan ih/serb ih, tiotropium cairan ih); \n19. Obat untuk syok Kardiogenik dan sepsis (Epinefrin/ adrenelin inj); \n20. Anastetik Lokal (Etil klorida sprey, lidokain inj/gel/spray topikal, anestetik lokal gigi kombinasi lidokain-epinefrin); \n21. Antiherpes (asiklovir tab 200mg/400mg); \n22. Antihiperlipidemia (Simvastatin Tab 10mg/20mg/40mg, atorvastatin 10mg/20mg, Rosuvastatin 10mg); \n23. Antiskabies (Permetrin krim 5%, salep 24); \n24. Antiseptik (hidrogen peroksida lar 3%, Povidon Iodin, Klorheksidin lar 1-2%); \n25. Antiangina (ISDN 5 mg/10mg, Gliseril trinitrat 0,5mg/2,5mg/5mg, Amlodipin tab 5mg, atenolol tab 50mg, diltiazem 30mg); \n26. Antifungi sistemik (griseovulvin tab 125mg/250mg/500mg, ketokonazol tab 200mg, nistatin tab/susp);\n27.  Obat batuk ( n-asetilsistein kap/sir, kodein tab 10mg/15mg/20mg); \n28. Obat Tuberkulosis (OAT Kategori1); \n29. Obat Malaria (primakuin tab 15mg, Kombinasi dihidroartemisin-piperakuin); \n30. Obat HIV/AIDS (Kombinasi TLE, Kombinasi TLD); \n31. Gizi Ibu Hamil dan Rematri (asam folat 0,4mg/ 1mg/5mg, ferosulfat tab/sirup, kombinasi Fe-asam folat, Sianokobalamin  tab/inj); \n32. Gizi Balita (vitamin A kapsul lunak 100000Iu/200000IU); \n33. Obat yang mempengaruhi koagulasi (Fitomenadion/Vitamin K tab/inj, Warfarin 1mg/2mg, asam tranexamat kaps,inj); \n34. Oksitoksik ( Metilergometrin tab/inj, oksitosin inj); \n35. Antelmintik (albensazol tab/susp, pirantel pamoat tab/susp, mebendazol tab/susp, prazikuantel tab 600mg); \n36. Obat untuk diare (garam oralit, zink, atapulgit, kombinasi mengandung kaolin dan pektin); \n37. Antimikroba untuk mata (gentamisin salep mata/tetes mata, kloramfenikol tetes mata/salep mata, oksitetrasiklin salep mata); \n38. Antipsikotik (haloperidol tab 0,5mg/1,5mg/2mg/5mg, haloperidol drops 2mg/ml, haloperidol inj 5mg/ml, haloperidol dekanoat inj 50mg/ml, flufenazin dekanoat inj 25mg/ml, aripripazol tab 10mg/15mg, klorpromazin tab 25mg/100mg, klorpromazin inj, klozapin tab 100mg, olanzapin tab 5mg/10mg, paliperidon palmitat inj, quetiapin tab, risperidon tab, trifluoperazin 5 mg); \n39. Antiansietas (diazepam 2mg/5mg, Diazepam inj 5 mg/ml, lorazepam tab 0,5mg/1mg/2mg); \n40. Antiepilepsi-antikonvulsi (Diazepam inj, diazepam enema, fenitoin kaps30mg/100mg, fenitoin inj, fenobarbital inj, fenobarbital tab 30mg/100mg, karbamazepin tab/sirup, magnesium sulfat 20%/40%, oskarbazepin susp 60mg/ml, valproat tab/sirup)","cara_penghitungan_raw":"- Melaporkan salah satu obat dengan tingkat ketersediaan tertinggi untuk setiap nomenklatur\n- Cara perhitungan ketersediaan = Jumlah Nomenklatur obat yang tersedia dibagi 40 dikali 100 %\n","target":{"raw":0.9,"excel_number_format":"0%"},"sumber_data_raw":"Aplikasi E Monev","keterangan_raw":null,"review":{"formula_family":"FIXED_ITEM_CHECKLIST","note":"Nomenklatur yang tersedia/40 × 100; jangan menjumlahkan alternatif obat dalam nomenklatur yang sama.","approval_required":true}}', 2026),
