('DO26-K2-R7', 'DO_2026_V2', 'K2-R8', 'Kunjungan antenatal pertama pada trimester 1 (sebelum atau sama dengan 12 minggu) dibagi seluruh sasaran ibu hamil di suatu wilayah kerja dengan kurun waktu dalam 1 tahun yang sama.', 'Jumlah Ibu hamil yang mendapatkan pelayanan ANC sesuai standar (K1 Murni) dibagi sasaran ibu hamil dikali 100%', 'Laporan PWS KIA - Sigizi Kesga', NULL, '90%', 'S1:KLASTER 2!A7:I7', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K2-R7","catalogue_candidate":"K2-R8","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"KLASTER 2","row":7,"range":"A7:I7"},"no_raw":null,"kegiatan_raw":"Pelayanan Kesehatan Ibu Hamil","indikator_raw":"Kunjungan Pertama Ibu Hamil (K1 Murni)","definisi_operasional_raw":"Kunjungan antenatal pertama pada trimester 1 (sebelum atau sama dengan 12 minggu) dibagi seluruh sasaran ibu hamil di suatu wilayah kerja dengan kurun waktu dalam 1 tahun yang sama.","cara_penghitungan_raw":"Jumlah Ibu hamil yang mendapatkan pelayanan ANC sesuai standar (K1 Murni) dibagi sasaran ibu hamil dikali 100%","target":{"raw":0.9,"excel_number_format":"0%"},"sumber_data_raw":"Laporan PWS KIA - Sigizi Kesga","keterangan_raw":null,"review":{"formula_family":"SOURCE_DEFINED_REVIEW_REQUIRED","note":"Baca seluruh syarat definisi dan cara hitung. Profil waktu, penyebut, skor dan applicability belum diaktifkan ke runtime.","approval_required":true}}', 2026),
('DO26-K2-R8', 'DO_2026_V2', 'K2-R9', '"Ibu hamil yang mendapatkan pelayanan ANC sesuai standar adalah ibu hamil yang telah bersalin serta mendapatkan pelayanan ANC lengkap sesuai dengan standar kuantitas dan standar kualitas selama periode kehamilan di wilayah kerja Puskesmas pada tahun berjalan. 
Pelayanan kesehatan masa hamil dilakukan paling sedikit 6 (enam) kali. 1 (satu) kali pada trimester pertama, 2 (dua) kali pada trimester kedua, 3 (tiga) kali pada trimester ketiga. Ibu hamil paling sedikit kontak dengan dokter 2 (dua) kali yaitu 1 (satu) kali di trimester pertama dan 1 (satu) kali di trimester ketiga. Pelayanan sesuai standar meliputi 12T yaitu: 
 1. Pengukuran berat badan dan tinggi badan
 2. Pengukuran tekanan darah
 3. Pengukuran lingkar lengan atas (LiLA)
 4. Pengukuran tinggi fundus uteri
 5. Penentuan presentasi janin dan denyut jantung janin
 6. Imunisasi
 7. Pemberian tablet tambah darah
 8. Laboratorium (Golongan darah, Hb, Gluko protein urin, HIV) 
 9. Tata laksana
 10. Temu wicara
11. USG Dasar Terbatas oleh dokter
12. Skrining Kejiwaan', 'Jumlah ibu hamil yang memperoleh pelayanan antenatal 6x sesuai standar di wilayah kerja pada kurun waktu tertentu dibagi Jumlah seluruh sasaran ibu bersalin di suatu wilayah tersebut pada kurun waktu yang sama dikali 100%', 'Laporan PWS KIA - Sigizi Kesga', NULL, '82%', 'S1:KLASTER 2!A8:I8', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K2-R8","catalogue_candidate":"K2-R9","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"KLASTER 2","row":8,"range":"A8:I8"},"no_raw":"2.","kegiatan_raw":"Pelayanan Kesehatan Ibu Hamil","indikator_raw":"Ibu hamil yang mendapatkan pemeriksaan kehamilan 6 kali (K6)","definisi_operasional_raw":"\"Ibu hamil yang mendapatkan pelayanan ANC sesuai standar adalah ibu hamil yang telah bersalin serta mendapatkan pelayanan ANC lengkap sesuai dengan standar kuantitas dan standar kualitas selama periode kehamilan di wilayah kerja Puskesmas pada tahun berjalan. \nPelayanan kesehatan masa hamil dilakukan paling sedikit 6 (enam) kali. 1 (satu) kali pada trimester pertama, 2 (dua) kali pada trimester kedua, 3 (tiga) kali pada trimester ketiga. Ibu hamil paling sedikit kontak dengan dokter 2 (dua) kali yaitu 1 (satu) kali di trimester pertama dan 1 (satu) kali di trimester ketiga. Pelayanan sesuai standar meliputi 12T yaitu: \n 1. Pengukuran berat badan dan tinggi badan\n 2. Pengukuran tekanan darah\n 3. Pengukuran lingkar lengan atas (LiLA)\n 4. Pengukuran tinggi fundus uteri\n 5. Penentuan presentasi janin dan denyut jantung janin\n 6. Imunisasi\n 7. Pemberian tablet tambah darah\n 8. Laboratorium (Golongan darah, Hb, Gluko protein urin, HIV) \n 9. Tata laksana\n 10. Temu wicara\n11. USG Dasar Terbatas oleh dokter\n12. Skrining Kejiwaan","cara_penghitungan_raw":"Jumlah ibu hamil yang memperoleh pelayanan antenatal 6x sesuai standar di wilayah kerja pada kurun waktu tertentu dibagi Jumlah seluruh sasaran ibu bersalin di suatu wilayah tersebut pada kurun waktu yang sama dikali 100%","target":{"raw":0.82,"excel_number_format":"0%"},"sumber_data_raw":"Laporan PWS KIA - Sigizi Kesga","keterangan_raw":null,"review":{"formula_family":"COHORT_SERVICE_COVERAGE","note":"Pembilang K6 adalah ibu yang telah bersalin; penyebutnya sasaran ibu bersalin, bukan otomatis sasaran bumil.","approval_required":true}}', 2026),
('DO26-K2-R9', 'DO_2026_V2', 'K2-R10', 'Persentase Ibu hamil yang mendapatkan suplementasi gizi dalam bentuk tablet tambah darah atau Multiple Micronutrient Supplementation (MMS) sesuai standar minimal 180 tablet dalam kurun waktu satu tahun yang sama di suatu wilayah kerja', '(Jumlah ibu hamil yang mendapatkan suplementasi gizi sesuai standar minimal 180 tablet dalam kurun satu tahun di suatu wilayah kerja dibagi jumlah sasaran ibu hamil dalam kurun satu tahun yang sama di suatu wilayah kerja) dikali 100%', 'lap sigizi kesga (indikator ibu hamil )', 'kolom 16', '92%', 'S1:KLASTER 2!A9:I9', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K2-R9","catalogue_candidate":"K2-R10","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"KLASTER 2","row":9,"range":"A9:I9"},"no_raw":"3.","kegiatan_raw":"Pelayanan Kesehatan Ibu Hamil","indikator_raw":"Persentase Ibu hamil mendapat suplementasi gizi","definisi_operasional_raw":"Persentase Ibu hamil yang mendapatkan suplementasi gizi dalam bentuk tablet tambah darah atau Multiple Micronutrient Supplementation (MMS) sesuai standar minimal 180 tablet dalam kurun waktu satu tahun yang sama di suatu wilayah kerja","cara_penghitungan_raw":"(Jumlah ibu hamil yang mendapatkan suplementasi gizi sesuai standar minimal 180 tablet dalam kurun satu tahun di suatu wilayah kerja dibagi jumlah sasaran ibu hamil dalam kurun satu tahun yang sama di suatu wilayah kerja) dikali 100%","target":{"raw":0.92,"excel_number_format":"0%"},"sumber_data_raw":"lap sigizi kesga (indikator ibu hamil )","keterangan_raw":"kolom 16","review":{"formula_family":"SOURCE_DEFINED_REVIEW_REQUIRED","note":"Baca seluruh syarat definisi dan cara hitung. Profil waktu, penyebut, skor dan applicability belum diaktifkan ke runtime.","approval_required":true}}', 2026),
('DO26-K2-R10', 'DO_2026_V2', 'K2-R11', 'Persentase Ibu hamil yang mempunyai Indeks Massa Tubuh Pra hamil atau pada Trimester 1 (< 12 minggu) sebesar < 18,5 kg/m2 dan atau Ibu hamil yang mempunyai ukuran Lingkar Lengan Atas (LiLA) kurang dari 23,5 cm yang mendapatkan makanan tambahan berbahan pangan lokal dalam kurun waktu satu tahun di suatu wilayah kerja', '(Jumlah ibu hamil yang teridentifikasi KEK dan risiko KEK yang mendapatkan makanan tambahan dalam kurun waktu satu tahun di suatu wilayah kerja dibagi jumlah ibu hamil KEK dan risiko KEK dalam kurun waktu satu tahun yang sama di suatu wilayah kerja) x 100%', 'lap sigizi kesga (indikator ibu hamil )', 'kolom 24', '85%', 'S1:KLASTER 2!A10:I10', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K2-R10","catalogue_candidate":"K2-R11","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"KLASTER 2","row":10,"range":"A10:I10"},"no_raw":"4.","kegiatan_raw":"Pelayanan Kesehatan Ibu Hamil","indikator_raw":"Persentase Ibu hamil KEK mendapat makanan tambahan","definisi_operasional_raw":"Persentase Ibu hamil yang mempunyai Indeks Massa Tubuh Pra hamil atau pada Trimester 1 (< 12 minggu) sebesar < 18,5 kg/m2 dan atau Ibu hamil yang mempunyai ukuran Lingkar Lengan Atas (LiLA) kurang dari 23,5 cm yang mendapatkan makanan tambahan berbahan pangan lokal dalam kurun waktu satu tahun di suatu wilayah kerja","cara_penghitungan_raw":"(Jumlah ibu hamil yang teridentifikasi KEK dan risiko KEK yang mendapatkan makanan tambahan dalam kurun waktu satu tahun di suatu wilayah kerja dibagi jumlah ibu hamil KEK dan risiko KEK dalam kurun waktu satu tahun yang sama di suatu wilayah kerja) x 100%","target":{"raw":0.85,"excel_number_format":"0%"},"sumber_data_raw":"lap sigizi kesga (indikator ibu hamil )","keterangan_raw":"kolom 24","review":{"formula_family":"SOURCE_DEFINED_REVIEW_REQUIRED","note":"Baca seluruh syarat definisi dan cara hitung. Profil waktu, p