('DO26-K2-R14', 'DO_2026_V2', 'K2-R15', 'Penanganan komplikasi kebidanan, yaitu penyakit menular maupun tidak menular serta masalah gizi yang terjadi pada waktu hamil, bersalin dan nifas, abortus, perdarahan, Pre eklamsi/ eklamsi, persalinan macet, infeksi, abortus, malaria, HIV/AIDS, Sifilis, Hepatitis, TB, hipertensi, diabetes melitus, anemia gizi besi dan Kurang Energi Kronis (KEK), dll oleh tenaga kesehatan yang mempunyai kompetensi', 'Jumlah ibu hamil,bersalin dan nifas dengan komplikasi kebidanan yang mendapatkan penanganan definitif (sampai selesai) dibagi 20% sasaran ibu hamil dikali 100%', 'Laporan PWS KIA', NULL, '100%', 'S1:KLASTER 2!A14:I14', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K2-R14","catalogue_candidate":"K2-R15","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"KLASTER 2","row":14,"range":"A14:I14"},"no_raw":"8.","kegiatan_raw":"Pelayanan ibu hamil, bersalin dan nifas","indikator_raw":"Penanganan komplikasi kebidanan (PK)","definisi_operasional_raw":"Penanganan komplikasi kebidanan, yaitu penyakit menular maupun tidak menular serta masalah gizi yang terjadi pada waktu hamil, bersalin dan nifas, abortus, perdarahan, Pre eklamsi/ eklamsi, persalinan macet, infeksi, abortus, malaria, HIV/AIDS, Sifilis, Hepatitis, TB, hipertensi, diabetes melitus, anemia gizi besi dan Kurang Energi Kronis (KEK), dll oleh tenaga kesehatan yang mempunyai kompetensi","cara_penghitungan_raw":"Jumlah ibu hamil,bersalin dan nifas dengan komplikasi kebidanan yang mendapatkan penanganan definitif (sampai selesai) dibagi 20% sasaran ibu hamil dikali 100%","target":{"raw":1,"excel_number_format":"0%"},"sumber_data_raw":"Laporan PWS KIA","keterangan_raw":null,"review":{"formula_family":"ESTIMATED_DENOMINATOR","note":"Penyebut adalah 20% × sasaran bumil, bukan seluruh bumil.","approval_required":true}}', 2026),
('DO26-K2-R15', 'DO_2026_V2', 'K2-R16', 'Semua ibu hamil yang diperiksa HBsAg di sarana kesehatan dalam kurun waktu tertentu', 'Pemeriksaan HBsAg pada ibu hamil dengan RDT HBsAg (baik dari Kemenkes atau APBD II) dan pemeriksaan metode lain.
