('DO26-K2-R30', 'DO_2026_V2', 'K2-R31', 'Persentase bayi dari ibu Hepatitis B Reaktif usia 9-12 bulan yang diperiksa/dipantau HBsAg nya', 'Jumlah bayi dari ibu dengan Hepatitis B Reaktif di usia 9-12 bulan (maksimal usia 18 bulan) yang diperiksa/ dipantau dengan hasil HBsAg Non Reaktif dibagi dengan jumlah bayi dari ibu dengan Hepatitis B Reaktif di usia 9-12 bulan (maksimal usia 18 bulan) yang diperiksa/ dipantau HBsAg nya dikali 100%', 'Pencatatan dan Pelaporan Hepatitis B, Worksheet Tahunan, 100%-Kolom 45 atau SIHEPI, Laporan Tahunan 3E (3E3), 100%-Kolom 45', NULL, '≥95%', 'S1:KLASTER 2!A30:I30', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K2-R30","catalogue_candidate":"K2-R31","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"KLASTER 2","row":30,"range":"A30:I30"},"no_raw":"9.","kegiatan_raw":"Tatalaksana Bayi yang lahir dari ibu dengan Hepatitis B Reaktif","indikator_raw":"Pemantauan Bayi usia 9-12 bulan yang lahir dari ibu dengan Hepatitis B dengan hasil HBsAg Non Reaktif","definisi_operasional_raw":"Persentase bayi dari ibu Hepatitis B Reaktif usia 9-12 bulan yang diperiksa/dipantau HBsAg nya","cara_penghitungan_raw":"Jumlah bayi dari ibu dengan Hepatitis B Reaktif di usia 9-12 bulan (maksimal usia 18 bulan) yang diperiksa/ dipantau dengan hasil HBsAg Non Reaktif dibagi dengan jumlah bayi dari ibu dengan Hepatitis B Reaktif di usia 9-12 bulan (maksimal usia 18 bulan) yang diperiksa/ dipantau HBsAg nya dikali 100%","target":{"raw":"≥95%","excel_number_format":"0%"},"sumber_data_raw":"Pencatatan dan Pelaporan Hepatitis B, Worksheet Tahunan, 100%-Kolom 45 atau SIHEPI, Laporan Tahunan 3E (3E3), 100%-Kolom 45","keterangan_raw":null,"review":{"formula_family":"SOURCE_DEFINED_REVIEW_REQUIRED","note":"Baca seluruh syarat definisi dan cara hitung. Profil waktu, penyebut, skor dan applicability belum diaktifkan ke runtime.","approval_required":true}}', 2026),
('DO26-K2-R31', 'DO_2026_V2', 'K2-R32', 'Persentase bayi dari ibu Hepatitis B Reaktif usia 9-12 bulan yang diperiksa Anti HBs nya', 'Jumlah bayi dari ibu dengan Hepatitis B Reaktif di usia 9-12 bulan (maksimal usia 18 bulan) dengan HBsAg Non Reaktif lanjut periksa Anti HBs.
