('DO26-K2-R37', 'DO_2026_V2', 'K2-R38', 'Persentase balita usia 0-59 bulan yang memiliki tanda klinis gizi buruk dan atau bayi dengan risiko pertumbuhan dan perkembangan buruk pada usia <6 bulan atau Indeks BB/PB atau BB/TB dengan nilai Z-score kurang dari -3 SD atau Lingkar Lengan Atas (LiLA) kurang dari 11.5 cm pada balita usia 6-59 bulan yang dirawat inap maupun rawat jalan di fasilitas pelayanan kesehatan dan masyarakat sesuai dengan tata laksana gizi buruk.', '(Jumlah balita usia 0-59 bulan gizi buruk yang mendapat tata laksana gizi buruk sesuai standar dibagi Jumlah seluruh balita usia 0-59 bulan gizi buruk pada suatu wilayah kerja) dikali 100%', 'Sigizi Kesga (indikator balita gizi )', 'kolom 48', '92%', 'S1:KLASTER 2!A37:I37', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K2-R37","catalogue_candidate":"K2-R38","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"KLASTER 2","row":37,"range":"A37:I37"},"no_raw":"5.","kegiatan_raw":"Pelayanan Kesehatan Balita","indikator_raw":"Persentase balita gizi buruk mendapat tatalaksana","definisi_operasional_raw":"Persentase balita usia 0-59 bulan yang memiliki tanda klinis gizi buruk dan atau bayi dengan risiko pertumbuhan dan perkembangan buruk pada usia <6 bulan atau Indeks BB/PB atau BB/TB dengan nilai Z-score kurang dari -3 SD atau Lingkar Lengan Atas (LiLA) kurang dari 11.5 cm pada balita usia 6-59 bulan yang dirawat inap maupun rawat jalan di fasilitas pelayanan kesehatan dan masyarakat sesuai dengan tata laksana gizi buruk.","cara_penghitungan_raw":"(Jumlah balita usia 0-59 bulan gizi buruk yang mendapat tata laksana gizi buruk sesuai standar dibagi Jumlah seluruh balita usia 0-59 bulan gizi buruk pada suatu wilayah kerja) dikali 100%","target":{"raw":0.92,"excel_number_format":"0%"},"sumber_data_raw":"Sigizi Kesga (indikator balita gizi )","keterangan_raw":"kolom 48","review":{"formula_family":"SOURCE_DEFINED_REVIEW_REQUIRE