('DO26-K2-R38', 'DO_2026_V2', 'K2-R39', 'Anak yang berusia 0 bulan sampai 59 bulan yang di timbang berat badannya (D/S)', 'Jumlah balita di timbang (D) di bagi Jumlah balita yang ada (S) di kali 100 %', 'Sigizi Kesga indiator balita gizi  ', 'kolom 6', '90%', 'S1:KLASTER 2!A38:I38', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K2-R38","catalogue_candidate":"K2-R39","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"KLASTER 2","row":38,"range":"A38:I38"},"no_raw":"6.","kegiatan_raw":"Pelayanan Kesehatan Balita","indikator_raw":"Cakupan balita yang ditimbang Berat Badannya (D/S)","definisi_operasional_raw":"Anak yang berusia 0 bulan sampai 59 bulan yang di timbang berat badannya (D/S)","cara_penghitungan_raw":"Jumlah balita di timbang (D) di bagi Jumlah balita yang ada (S) di kali 100 %","target":{"raw":0.9,"excel_number_format":"0%"},"sumber_data_raw":"Sigizi Kesga indiator balita gizi  ","keterangan_raw":"kolom 6","review":{"formula_family":"PERIOD_POPULATION_RATIO","note":"D/S harus sesuai dengan bulan/anak; jangan menjumlahkan prevalensi atau menghitung kunjungan berulang sebagai anak unik.","approval_required":true}}', 2026),
('DO26-K2-R39', 'DO_2026_V2', 'K2-R40', 'Proporsi jumlah penerima pemeriksaan gratis kelompok usia balita dan anak usia pra sekolah terhadap total penduduk kelompok usia balita dan anak usia pra sekolah
Skrining pada kelompok usia balita dan anak usia pra sekolah adalah skrining pertumbuhan, perkembangan, mata, telinga, gigi, dan tuberkulosis, serta skrining hepatitis B, C dan sirosis untuk kelompok risiko', 'Jumlah kelompok usia balita dan anak prasekolah umur 1-6 tahun yang memperoleh paket layanan pemeriksaan kesehatan gratis dibagi sasaran balita dan anak prasekolah umur 1-6 tahun dikali 100%', 'ASIK Website', NULL, '55.00000000000001%', 'S1:KLASTER 2!A39:I39', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K2-R39","catalogue_candidate":"K2-R40","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"KLASTER 2","row":39,"range":"A39:I39"},"no_raw":"7.","kegiatan_raw":"Pemeriksaan kesehatan gratis (PKG) kelompok usia balita dan anak prasekolah","indikator_raw":"Persentase penduduk penerima pemeriksaan kesehatan gratis kelompok usia balita dan anak prasekolah (%)","definisi_operasional_raw":"Proporsi jumlah penerima pemeriksaan gratis kelompok usia balita dan anak usia pra sekolah terhadap total penduduk kelompok usia balita dan anak usia pra sekolah\nSkrining pada kelompok usia balita dan anak usia pra sekolah adalah skrining pertumbuhan, perkembangan, mata, telinga, gigi, dan tuberkulosis, serta skrining hepatitis B, C dan sirosis untuk kelompok risiko","cara_penghitungan_raw":"Jumlah kelompok usia balita dan anak prasekolah umur 1-6 tahun yang memperoleh paket layanan pemeriksaan kesehatan gratis dibagi sasaran balita dan anak prasekolah umur 1-6 tahun dikali 100%","target":{"raw":0.55,"excel_number_format":"0%"},"sumber_data_raw":"ASIK Website","keterangan_raw":null,"review":{"formula_family":"SOURCE_DEFINED_REVIEW_REQUIRED","note":"Baca seluruh syarat definisi dan cara hitung. Profil waktu, penyebut, skor dan applicability belum diaktifkan ke runtime.","approval_required":true}}', 2026),
('DO26-K2-R41', 'DO_2026_V2', 'K2-R42', 'Penemuan kasus diare balita di sarana kesehatan di wilayah kerja Puskesmas pada kurun waktu tertentu.', 'Jumlah penderita diare balita yang datang dan dilayani di sarana kesehatan dibagi target dikali 100%.
Target = 70% x prevalensi balita diare pada kurun waktu tertentu x jumlah balita.  
Balita adalah anak usia 0-59 bulan. 
Jumlah balita sesuai KMK Data Penduduk Sasaran Program Pembangunan Kesehatan Tahun 2026-2030.
Prevalensi balita diare sesuai SKI 2023 menurut provinsi Jawa Timur, yaitu sebesar 6,5%.  
Target = 70% x 6,5% dikali jumlah balita  ', 'Laporan Register Penyakit Diare pada worksheet DIARE REKAP, Kolom 16 atau SIHEPI, Laporan Diare Tahunan, Kolom 16', NULL, '100%', 'S1:KLASTER 2!A41:I41', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K2-R41","catalogue_candidate":"K2-R42","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"KLASTER 2","row":41,"range":"A41:I41"},"no_raw":"1.","kegiatan_raw":"Pencegahan dan Pengendalian Penyakit Diare","indikator_raw":"Cakupan Penanganan Kasus Diare Balita ","definisi_operasional_raw":"Penemuan kasus diare balita di sarana kesehatan di wilayah kerja Puskesmas pada kurun waktu tertentu.","cara_penghitungan_raw":"Jumlah penderita diare balita yang datang dan dilayani di sarana kesehatan dibagi target dikali 100%.\nTarget = 70% x prevalensi balita diare pada kurun waktu tertentu x jumlah balita.  \nBalita adalah anak usia 0-59 bulan. \nJumlah balita sesuai KMK Data Penduduk Sasaran Program Pembangunan Kesehatan Tahun 2026-2030.\nPrevalensi balita diare sesuai SKI 2023 menurut provinsi Jawa Timur, yaitu sebesar 6,5%.  \nTarget = 70% x 6,5% dikali jumlah balita  ","target":{"raw":1,"excel_number_format":"0%"},"sumber_data_raw":"Laporan Register Penyakit Diare pada worksheet DIARE REKAP, Kolom 16 atau SIHEPI, Laporan Diare Tahunan, Kolom 16","keterangan_raw":null,"review":{"formula_family":"ESTIMATED_DENOMINATOR","note":"Denominator = 0.70 × 0.065 × balita 0–59 bulan, berdasarkan F41 dalam konteks Jawa Timur; bukan faktor universal.","approval_required":true}}', 2026),
('DO26-K2-R42', 'DO_2026_V2', 'K2-R43', 'Penderita balita diare yang berobat mendapat oralit dan tablet Zinc di sarana kesehatan di wilayah kerja Puskesmas pada kurun waktu tertentu', 'Jumlah penderita balita diare yang mendapat oralit dan tablet Zinc yang datang dan dilayani di sarana kesehatan dibagi total penderita balita diare di sarana kesehatan dikali 100 %', 'Laporan Register Penyakit Diare pada worksheet DIARE REKAP, Kolom 43 atau SIHEPI, Laporan Diare Tahunan, Kolom 43', NULL, '100%', 'S1:KLASTER 2!A42:I42', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K2-R42","catalogue_candidate":"K2-R43","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"KLASTER 2","row":42,"range":"A42:I42"},"no_raw":"2.","kegiatan_raw":"Pencegahan dan Pengendalian Penyakit Diare","indikator_raw":"Cakupan Pemberian Oralit dan Zinc pada Penderita Balita Diare ","definisi_operasional_raw":"Penderita balita diare yang berobat mendapat oralit dan tablet Zinc di sarana kesehatan di wilayah kerja Puskesmas pada kurun waktu tertentu","cara_penghitungan_raw":"Jumlah penderita balita diare yang mendapat oralit dan tablet Zinc yang datang dan dilayani di sarana kesehatan dibagi total penderita balita diare di sarana kesehatan dikali 100 %","target":{"raw":1,"excel_number_format":"0%"},"sumber_data_raw":"Laporan Register Penyakit Diare pada worksheet DIARE REKAP, Kolom 43 atau SIHEPI, Laporan Diare Tahunan, Kolom 43","keterangan_raw":null,"review":{"formula_family":"SOURCE_DEFINED_REVIEW_REQUIRED","note":"Baca seluruh syarat definisi dan cara hitung. Profil waktu, penyebut, skor dan applicability belum diaktifkan ke runtime.","approval_required":true}}', 2026),
('DO26-K2-R43', 'DO_2026_V2', 'K2-R44', 'LROA aktif bila melakukan minimal 2 (dua) dari 6 kegiatan LRO, yaitu:
1. Layanan konseling rehidrasi diare/promosi upaya rehidrasi oral dan pemberian zinc
2. Tatalaksana diare
3. Sosialisasi dan peningkatan kapasitas masyarakat tentang diare dan upaya pencegahan dan penanggulangannya 
4. Pemberian pelayanan penderita diare dengan dehidrasi ringan sampai sedang 
5. Observasi penderita diare dengan dehidrasi ringan sampai sedang paling sedikit 3 ( tiga) jam 
6. Mengajarkan cara penyiapan oralit dan berapa banyak oralit yang harus diminum kepada orang tua/pengasuh/ keluarganya', 'Layanan kegiatan LROA secara terus menerus dalam 3 bulan dengan periode pelaporan per tribulan.
Dalam 1 tribulan, laporan bulanan harus ada dan lengkap.
Kalau dalam 1 tribulan hanya ada laporan 1 bulan, maka dianggap tidak ada LROA.
Kalau dalam 1 tahun hanya lapor tribulan 4 saja, dianggap kinerja mencapai 25%. (Yang dihitung adalah jumlah layanan).', 'Aplikasi SIHEPI Online, Laporan LROA di bagian Laporan PISP', NULL, '100%', 'S1:KLASTER 2!A43:I43', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K2-R43","catalogue_candidate":"K2-R44","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"KLASTER 2","row":43,"range":"A43:I43"},"no_raw":"3.","kegiatan_raw":"Pencegahan dan Pengendalian Penyakit Diare","indikator_raw":"Pelaksanaan kegiatan Layanan Rehidrasi Oral Aktif (LROA) ","definisi_operasional_raw":"LROA aktif bila melakukan minimal 2 (dua) dari 6 kegiatan LRO, yaitu:\n1. Layanan konseling rehidrasi diare/promosi upaya rehidrasi oral dan pemberian zinc\n2. Tatalaksana diare\n3. Sosialisasi dan peningkatan kapasitas masyarakat tentang diare dan upaya pencegahan dan penanggulangannya \n4. Pemberian pelayanan penderita diare dengan dehidrasi ringan sampai sedang \n5. Observasi penderita diare dengan dehidrasi ringan sampai sedang paling sedikit 3 ( tiga) jam \n6. Mengajarkan cara penyiapan oralit dan berapa banyak oralit yang harus diminum kepada orang tua/pengasuh/ keluarganya","cara_penghitungan_raw":"Layanan kegiatan LROA secara terus menerus dalam 3 bulan dengan periode pelaporan per tribulan.\nDalam 1 tribulan, laporan bulanan harus ada dan lengkap.\nKalau dalam 1 tribulan hanya ada laporan 1 bulan, maka dianggap tidak ada LROA.\nKalau dalam 1 tahun hanya lapor tribulan 4 saja, dianggap kinerja mencapai 25%. (Yang dihitung adalah jumlah layanan).","target":{"raw":1,"excel_number_format":"0%"},"sumber_data_raw":"Aplikasi SIHEPI Online, Laporan LROA di bagian Laporan PISP","keterangan_raw":null,"review":{"formula_family":"QUARTER_COMPLETENESS","note":"LROA per triwulan memerlukan 3 laporan bulanan yang lengkap; satu bulan saja tidak lulus; dalam setahun hanya TW4 => 25.","approval_required":true}}', 2026),
