('DO26-K5-R12', 'DO_2026_V2', 'K5-R13', 'Dokter Umum yang bertugas Ruang Pelayanan Gawat Darurat mempunyai SIP di Puskesmas tersebut dan mempunyai Sertifikat Pelatihan Kegawatdaruratan yang masih berlaku diantaranya GELS, ATLS dan ACLS', 'Jumlah dokter umum yang bertugas di Ruang Pelayanan Gawat Darurat mempunyai sertifikat GELS, ATLS dan ACLS dibagi jumlah dokter umum yang bertugas di Ruang Pelayanan Gawat Darurat dikali 100%', NULL, NULL, '100%', 'S1:LINTAS KLASTER!A12:I12', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K5-R12","catalogue_candidate":"K5-R13","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"LINTAS KLASTER","row":12,"range":"A12:I12"},"no_raw":"2.","kegiatan_raw":"Kompetensi Dokter di Ruang Pelayanan Gawat Darurat","indikator_raw":"Dokter Umum Ruang Pelayanan Gawat Darurat telah mengikuti Pelatihan Kegawatdaruratan","definisi_operasional_raw":"Dokter Umum yang bertugas Ruang Pelayanan Gawat Darurat mempunyai SIP di Puskesmas tersebut dan mempunyai Sertifikat Pelatihan Kegawatdaruratan yang masih berlaku diantaranya GELS, ATLS dan ACLS","cara_penghitungan_raw":"Jumlah dokter umum yang bertugas di Ruang Pelayanan Gawat Darurat mempunyai sertifikat GELS, ATLS dan ACLS dibagi jumlah dokter umum yang bertugas di Ruang Pelayanan Gawat Darurat dikali 100%","target":{"raw":1,"excel_number_format":"0%"},"sumber_data_raw":null,"keterangan_raw":null,"review":{"formula_family":"SOURCE_DEFINED_REVIEW_REQUIRED","note":"Baca seluruh syarat definisi dan cara hitung. Profil waktu, penyebut, skor dan applicability belum diaktifkan ke runtime.","approval_required":true}}', 2026),
