('DO26-K5-R14', 'DO_2026_V2', 'K5-R15', 'Respon time (waktu tanggap) pelayanan di Ruang Gawat Darurat  adalah kecepatan waktu penanganan, yaitu waktu yang dibutuhkan sejak pasien tiba di depan pintu Ruang Pelayanan Gawat Darurat sampai mendapat penangan medis awal.', 'Jumlah pasien Ruang Pelayanan Gawat Darurat yang ditangani dengan respon time < 30 menit dibagi jumlah pasien Ruang Pelayanan Gawat Darurat dikali 100%', NULL, NULL, '80%', 'S1:LINTAS KLASTER!A14:I14', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K5-R14","catalogue_candidate":"K5-R15","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"LINTAS KLASTER","row":14,"range":"A14:I14"},"no_raw":"4.","kegiatan_raw":"Respon time pelayanan gawat darurat","indikator_raw":"Persentase respon time <30 menit untuk pelayanan di Ruang Pelayanan Gawat Darurat","definisi_operasional_raw":"Respon time (waktu tanggap) pelayanan di Ruang Gawat Darurat  adalah kecepatan waktu penanganan, yaitu waktu yang dibutuhkan sejak pasien tiba di depan pintu Ruang Pelayanan Gawat Darurat sampai mendapat penangan medis awal.","cara_penghitungan_raw":"Jumlah pasien Ruang Pelayanan Gawat Darurat yang ditangani dengan respon time < 30 menit dibagi jumlah pasien Ruang Pelayanan Gawat Darurat dikali 100%","target":{"raw":0.8,"excel_number_format":"0%"},"sumber_data_raw":null,"keterangan_raw":null,"review":{"formula_family":"SOURCE_DEFINED_REVIEW_REQUIRED","note":"Baca seluruh syarat definisi dan cara hitung. Profil waktu, penyebut, skor dan applicability belum diaktifkan ke runtime.","approval_required":true}}', 2026),
('DO26-K5-R15', 'DO_2026_V2', 'K5-R16', 'Jumlah Pasien gawat darurat yang perlu dirujuk ke FKRTL diperiksa dan distabilisasi terlebih dahulu sesuai dengan kemampuan Puskesmas dan dipastikan dapat diterima di FKRTL (SISRUTE) sesuai dengan kebijakan, pedoman dan prosedur yang ditetapkan ', 'Jumlah pasien gawat darurat yang perlu dirujuk ke FKRTL diperiksa dan distabilisasi terlebih dahulu sesuai dengan kemampuan Puskesmas dan dipastikan dapat diterima di FKRTL (SISRUTE) sesuai dengan kebijakan, pedoman dan prosedur yang ditetapkan / Jumlah total pasien yang masuk UGD yang di rujuk x 100%

Pasien gawat darurat dirujuk tidak diinput melalui SISRUTE = 0
Pasien gawat darurat dirujuk diinput melalui SISRUTE <30 % = 30 
Pasien gawat darurat dirujuk diinput melalui SISRUTE <30 - 80 % = 80 
Pasien gawat darurat dirujuk diinput melalui SISRUTE >80 % = 100 ', NULL, NULL, '30%', 'S1:LINTAS KLASTER!A15:I15', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K5-R15","catalogue_candidate":"K5-R16","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"LINTAS KLASTER","row":15,"range":"A15:I15"},"no_raw":"5.","kegiatan_raw":"Stabilisasi Pasien  gawat darurat yang perlu di rujuk","indikator_raw":"Pasien gawat darurat yang perlu dirujuk ke FKRTL diperiksa dan distabilisasi terlebih dahulu sesuai dengan kemampuan Puskesmas dan dipastikan dapat diterima di FKRTL sesuai dengan kebijakan, pedoman dan prosedur yang ditetapkan ","definisi_operasional_raw":"Jumlah Pasien gawat darurat yang perlu dirujuk ke FKRTL diperiksa dan distabilisasi terlebih dahulu sesuai dengan kemampuan Puskesmas dan dipastikan dapat diterima di FKRTL (SISRUTE) sesuai dengan kebijakan, pedoman dan prosedur yang ditetapkan ","cara_penghitungan_raw":"Jumlah pasien gawat darurat yang perlu dirujuk ke FKRTL diperiksa dan distabilisasi terlebih dahulu sesuai dengan kemampuan Puskesmas dan dipastikan dapat diterima di FKRTL (SISRUTE) sesuai dengan kebijakan, pedoman dan prosedur yang ditetapkan / Jumlah total pasien yang masuk UGD yang di rujuk x 100%\n\nPasien gawat darurat dirujuk tidak diinput melalui SISRUTE = 0\nPasien gawat darurat dirujuk diinput melalui SISRUTE <30 % = 30 \nPasien gawat darurat dirujuk diinput melalui SISRUTE <30 - 80 % = 80 \nPasien gawat darurat dirujuk diinput melalui SISRUTE >80 % = 100 ","target":{"raw":0.3,"excel_number_format":"0%"},"sumber_data_raw":null,"keterangan_raw":null,"review":{"formula_family":"SISRUTE_RUBRIC_UNRESOLVED","note":"F15 memuat rubrik SISRUTE 0/30/80/100; teks ''<30–80%'' ambigu dan batas 30/80 perlu dikonfirmasi.","approval_required":true}}', 2026),
