('DO26-K5-R19', 'DO_2026_V2', 'K5-R20', 'Sarana prasarana yang terstandar dalam pengelolaan sediaan farmasi (adanya pallet, rak obat, lemari obat, lemari narkotika psikotropika, lemari es untuk menyimpan obat, APAR, pengatur suhu, thermohigrometer, kartu stok) dan sarana pendukung farmasi klinik (alat peracikan obat, perkamen, etiket)', 'jumlah sarana prasarana yang dimiliki dibagi jumlah sarana prasarana pelayanan kefarmasian standar dikali 100%', NULL, 'daftar sarana prasanana pelayanana kefarmasian standar mengacu pada PMK 43 Tahun 2019 tentang puskesmas', '80%', 'S1:LINTAS KLASTER!A19:I19', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K5-R19","catalogue_candidate":"K5-R20","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"LINTAS KLASTER","row":19,"range":"A19:I19"},"no_raw":2,"kegiatan_raw":"Sarana Prasarana Pelayanan Kefarmasian","indikator_raw":"Persentase ketersediaan sarana prasarana pelayanan kefarmasian","definisi_operasional_raw":"Sarana prasarana yang terstandar dalam pengelolaan sediaan farmasi (adanya pallet, rak obat, lemari obat, lemari narkotika psikotropika, lemari es untuk menyimpan obat, APAR, pengatur suhu, thermohigrometer, kartu stok) dan sarana pendukung farmasi klinik (alat peracikan obat, perkamen, etiket)","cara_penghitungan_raw":"jumlah sarana prasarana yang dimiliki dibagi jumlah sarana prasarana pelayanan kefarmasian standar dikali 100%","target":{"raw":0.8,"excel_number_format":"0%"},"sumber_data_raw":null,"keterangan_raw":"daftar sarana prasanana pelayanana kefarmasian standar mengacu pada PMK 43 Tahun 2019 tentang puskesmas","review":{"formula_family":"SOURCE_DEFINED_REVIEW_REQUIRED","note":"Baca seluruh syarat definisi dan cara hitung. Profil waktu, penyebut, skor dan applicability belum diaktifkan ke runtime.","approval_required":true}}', 2026),
