('DO26-K5-R21', 'DO_2026_V2', 'K5-R22', 'Persentase kesesuaian item obat yang tersedia di Puskesmas terhadap Fornas FKTP. Perhitungan evaluasi kesesuaian item obat yang tersedia dengan Fornas dilakukan setiap bulan.', 'Jumlah obat yang sesuai dengan formularium nasional dibagi total jumlah obat yang tersedia di puskesmas dikali 100%', NULL, NULL, '80%', 'S1:LINTAS KLASTER!A21:I21', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K5-R21","catalogue_candidate":"K5-R22","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"LINTAS KLASTER","row":21,"range":"A21:I21"},"no_raw":4,"kegiatan_raw":"Kesesuaian item obat yang tersedia dalam Fornas","indikator_raw":"Persentase kesesuaian jumlah obat yang tersedia dalam formularium puskesmas yang sesuai dengan Formularium Nasional","definisi_operasional_raw":"Persentase kesesuaian item obat yang tersedia di Puskesmas terhadap Fornas FKTP. Perhitungan evaluasi kesesuaian item obat yang tersedia dengan Fornas dilakukan setiap bulan.","cara_penghitungan_raw":"Jumlah obat yang sesuai dengan formularium nasional dibagi total jumlah obat yang tersedia di puskesmas dikali 100%","target":{"raw":0.8,"excel_number_format":"0%"},"sumber_data_raw":null,"keterangan_raw":null,"review":{"formula_family":"SOURCE_DEFINED_REVIEW_REQUIRED","note":"Baca seluruh syarat definisi dan cara hitung. Profil waktu, penyebut, skor dan applicability belum diaktifkan ke runtime.","approval_required":true}}', 2026),
('DO26-K5-R22', 'DO_2026_V2', 'K5-R23', 'Penggunaan antibiotika pada penatalaksanaan kasus ISPA non pneumoni per lembar resep terhadap seluruh kasus tersebut. Penggunaan antibiotik pada penatalaksanaan kasus ISPA non-pneumonia memiliki batas toleransi maksimal sebesar 20%. Data sampel diambil dari resep 1 kasus per hari dengan urutan pertama dengan diagnosa penyakit misal seperti ISPA ats (acute upper respiratory tract infection) (diagnosa dokter/perawat tidak spesifik), pilek (common cold), batuk-pilek, otitis media, sinusitis atau dalam kode ICD X berupa J00, J01, J04, J05, J06, J10, J11.', 'Jumlah penggunaan Antibiotika pada ISPA non Pneumonia dibagi Jumlah kasus ISPA non Pneumonia dikali 100 %
  Catatan kinerja Puskesmas :
  ≤ 20% = 100%
  21-40 % =75%
  41-60 % = 50%
  61-80 % = 25%
  > 80 % = 0%', 'Aplikasi SIMONA', 'Nilai target adalah catatan kinerja puskesmas dari hasil perhitungan', '100%', 'S1:LINTAS KLASTER!A22:I22', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K5-R22","catalogue_candidate":"K5-R23","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"LINTAS KLASTER","row":22,"range":"A22:I22"},"no_raw":5,"kegiatan_raw":"Penggunaan Obat Rasional (POR)","indikator_raw":"Persentase Penggunaan antibiotika pada penatalaksanaan ISPA non pneumonia","definisi_operasional_raw":"Penggunaan antibiotika pada penatalaksanaan kasus ISPA non pneumoni per lembar resep terhadap seluruh kasus tersebut. Penggunaan antibiotik pada penatalaksanaan kasus ISPA non-pneumonia memiliki batas toleransi maksimal sebesar 20%. Data sampel diambil dari resep 1 kasus per hari dengan urutan pertama dengan diagnosa penyakit misal seperti ISPA ats (acute upper respiratory tract infection) (diagnosa dokter/perawat tidak spesifik), pilek (common cold), batuk-pilek, otitis media, sinusitis atau dalam kode ICD X berupa J00, J01, J04, J05, J06, J10, J11.","cara_penghitungan_raw":"Jumlah penggunaan Antibiotika pada ISPA non Pneumonia dibagi Jumlah kasus ISPA non Pneumonia dikali 100 %\n  Catatan kinerja Puskesmas :\n  ≤ 20% = 100%\n  21-40 % =75%\n  41-60 % = 50%\n  61-80 % = 25%\n  > 80 % = 0%","target":{"raw":1,"excel_number_format":"0%"},"sumber_data_raw":"Aplikasi SIMONA","keterangan_raw":"Nilai target adalah catatan kinerja puskesmas dari hasil perhitungan","review":{"formula_family":"POR_BRACKETS_UNRESOLVED","note":"Rasio persentase antibiotik ISPA; rubrik ≤20/21–40/41–60/61–80/>80 memiliki celah desimal.","approval_required":true}}', 2026),
('DO26-K5-R23', 'DO_2026_V2', 'K5-R24', 'Penggunaan antibiotika pada penatalaksanaan kasus diare non spesifik terhadap seluruh kasus tersebut. Penggunaan antibiotik pd penatalaksanaan kasus diare non-spesifik memiliki batas toleransi maksimal 8 %. Diare Non Spesifik meliputi Gastroenteritis, penyebab tidak jelas, virus, dll (non bakterial). Data sampel diambil dari resep 1 kasus per hari dengan urutan pertama dengan diagnosa penyakit ditulis diare mencret atau sejenisnya atau dalam kode ICD X berupa A09 dan K52.', 'Jumlah penggunaan Antibiotika pada diare non spesifik dibagi jumlah kasus diare non spesifik dikali 100 %
