('DO26-K5-R36', 'DO_2026_V2', 'K5-R37', 'Kepatuhan petugas laboratorium dalam melaksanakan pengujian bahan kontrol (QC) pada alat laboratorium sebelum sampel pasien dikerjakan, guna memastikan bahwa alat dan reagen dalam kondisi stabil dan akurat pada hari tersebut', 'Jumlah hari dilakukan kontrol dibagi Jumlah hari kerja pelayanan dikali 100%', 'Buku Register / buku dokumentasi', NULL, '30%', 'S1:LINTAS KLASTER!A36:I36', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K5-R36","catalogue_candidate":"K5-R37","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"LINTAS KLASTER","row":36,"range":"A36:I36"},"no_raw":6,"kegiatan_raw":"Pelaksanaan Pemantapan Mutu Internal (PMI)","indikator_raw":"Persentase tingkat kepatuhan pelaksanaan kontrol harian ","definisi_operasional_raw":"Kepatuhan petugas laboratorium dalam melaksanakan pengujian bahan kontrol (QC) pada alat laboratorium sebelum sampel pasien dikerjakan, guna memastikan bahwa alat dan reagen dalam kondisi stabil dan akurat pada hari tersebut","cara_penghitungan_raw":"Jumlah hari dilakukan kontrol dibagi Jumlah hari kerja pelayanan dikali 100%","target":{"raw":0.3,"excel_number_format":"0%"},"sumber_data_raw":"Buku Register / buku dokumentasi","keterangan_raw":null,"review":{"formula_family":"WORKDAY_AVAILABILITY","note":"Hari kontrol QC/hari kerja pelayanan × 100, bukan hari kalender.","approval_required":true}}', 2026),
