('DO26-K5-R41', 'DO_2026_V2', 'K5-R42', 'Rekonsiliasi obat adalah proses sistematis membandingkan daftar obat yang sedang dikonsumsi pasien (termasuk obat dengan resep dan suplemen herbal) denag resep baru/perintah pengobatan dokter Ruang Pelayanan Rawat Inap. Rekonsiliasi obat bertujuan mencegah medication error. Puskesmas melakukan rekonsiliasi obat pada pelayanan Rawat Inap sesuai perundang-undangan yang berlaku.', 'Jumlah pasien yang mengkonsumsi obat sesuai perintah dokter Pelayanan Rawat Inap dibadi jumlah pasien Ruang Pelayanan Rawat Inap dikali 100%.', NULL, NULL, '100%', 'S1:LINTAS KLASTER!A41:I41', 'c4baf039eb460c7ffe030b419973b78ce0739e6f92778fbb41f85f5d3ea22149', 'Indikator DO dan Target PKP 2026.xlsx', '{"id":"DO26-K5-R41","catalogue_candidate":"K5-R42","mapping_basis":"NORMALIZED_LABEL_AND_ACTIVITY","source":{"sheet":"LINTAS KLASTER","row":41,"range":"A41:I41"},"no_raw":"3.","kegiatan_raw":"Rekonsiliasi obat  pelayanan rawat inap","indikator_raw":"Pelaksanaan rekonsiliasi obat pada pelayanan rawat inap","definisi_operasional_raw":"Rekonsiliasi obat adalah proses sistematis membandingkan daftar obat yang sedang dikonsumsi pasien (termasuk obat dengan resep dan suplemen herbal) denag resep baru/perintah pengobatan dokter Ruang Pelayanan Rawat Inap. Rekonsiliasi obat bertujuan mencegah medication error. Puskesmas melakukan rekonsiliasi obat pada pelayanan Rawat Inap sesuai perundang-undangan yang berlaku.","cara_penghitungan_raw":"Jumlah pasien yang mengkonsumsi obat sesuai perintah dokter Pelayanan Rawat Inap dibadi jumlah pasien Ruang Pelayanan Rawat Inap dikali 100%.","target":{"raw":1,"excel_number_format":"0%"},"sumber_data_raw":null,"keterangan_raw":null,"review":{"formula_family":"SOURCE_DEFINED_REVIEW_REQUIRED","note":"Baca seluruh syarat definisi dan cara hitung. Profil waktu, penyebut, skor dan applicability belum diaktifkan ke runtime.","approval_required":true}}', 2026),
